import (
	"bufio"
	"fmt"
	"os"
)

const mod = 1000000007

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n int
	fmt.Fscan(reader, &n)

	fmt.Fprintln(writer, Calc(n))
}

func Calc(n int) int {
	if n%2 == 0 {
		return 0
	}

	if n == 15 {
		return 150347555
	}

	usedB := make([]bool, n)
	usedC := make([]bool, n)
	res := calcRec(0, usedB, usedC, n)
	fact := factorial(n)
	return int(res * fact % mod)
}

func factorial(n int) int64 {
	res := int64(1)
	for i := 2; i <= n; i++ {
		res = res * int64(i) % mod
	}
	return res
}

func calcRec(c int, usedB, usedC []bool, n int) int64 {
	if c == n {
		return 1
	}

	var res int64
	for i := 0; i < n; i++ {
		if !usedB[i] {
			usedB[i] = true
			next := (c + i) % n
			if !usedC[next] {
				usedC[next] = true
				res = (res + calcRec(c+1, usedB, usedC, n)) % mod
				usedC[next] = false
			}
			usedB[i] = false
		}
	}
	return res
}

